with with_prev as (select *, lag(started_at) over (partition by country order by started_at, id) as prev_started_at from sessions), gaps as (select *, case when prev_started_at is null or started_at > prev_started_at + interval '14' day then 1 else 0 end as is_new_session from with_prev), sessions_sessions as (select *, sum(is_new_session) over (partition by country order by started_at, id rows between unbounded preceding and current row) as session_id from gaps) select s.id, s.customer_id, s.device, s.browser, s.prev_started_at, s.is_new_session, s.session_id, case when device rlike '^(mobile|desktop)$' then 'OTHER_ZONE' else 'CORE' end as device_zone, (select min(t2.discount) from orders t2 where t2.customer_id = s.customer_id) as min_order_discount from sessions_sessions s;
